#!/usr/bin/env node

/**
 * Keep every deck's shared headmatter identical.
 *
 * Slidev has no mechanism for including headmatter, so each deck must repeat
 * `theme`, `addons`, the shiki config and the cpp-runner compiler flags in full.
 * Twelve hand-maintained copies drift; this script owns them instead.
 *
 * Each deck's headmatter is split in two by a marker comment:
 *
 *   ---
 *   layout: cover        <- the deck's own first-slide frontmatter, edit freely
 *   color: blue-light
 *   # == shared: generated by scripts/sync-headmatter.mjs — do not edit below ==
 *   theme: neversink     <- rewritten from SHARED below on every run
 *   …
 *   ---
 *
 * `title` and `info` are generated too, from common/lessons.json, so a lesson renamed
 * in the registry is renamed in its browser tab.
 *
 * On the first run (no marker yet) the shared keys are stripped out of the
 * existing headmatter wherever they sit, and re-emitted below the marker.
 *
 * Usage:
 *   node scripts/sync-headmatter.mjs           # rewrite every deck
 *   node scripts/sync-headmatter.mjs --check   # exit 1 if anything is stale
 */

import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const ROOT = path.resolve(__dirname, '..')
const SLIDES_DIR = path.join(ROOT, 'slides')

const registry = JSON.parse(fs.readFileSync(path.join(ROOT, 'common', 'lessons.json'), 'utf8'))

const MARKER = '# == shared: generated by scripts/sync-headmatter.mjs — do not edit below =='

/**
 * Recognises the marker whatever its exact wording, so changing MARKER above
 * does not orphan the old line inside every deck's own half.
 *
 * Note the marker must not contain `---`: Slidev's parser ends the headmatter
 * block at the first such run, even inside a YAML comment, which silently drops
 * `theme:` and every key below it.
 */
const MARKER_RE = /^#.*sync-headmatter\.mjs.*$/m

const COMPILER_FLAGS =
  '-Wall -Wextra -pedantic -pthread -pedantic-errors -Wno-format -Wno-format-security -Wno-format-extra-args -Wno-unused-result'

/**
 * The block every deck gets, verbatim. Top-level keys listed here are removed
 * from the deck's own half of the headmatter, so a key can be moved into this
 * block later without leaving a duplicate behind.
 */
const SHARED = `theme: neversink
transition: slide-left
highlighter: shiki
shiki:
  theme:
    dark: vitesse-dark
    light: vitesse-light
lineNumbers: true
draw:
  enabled: true
favicon: './C.png'
# The c/cpp runners come from common/setup/code-runners.ts (adds stdin support),
# NOT from slidev-addon-cpp-runner — keep the addon out of this list, or its
# runner can win over ours depending on setup load order.
c:
  compiler: 'g++'
  standard: 'c2x'
  optimization: 'O2'
  flags: '${COMPILER_FLAGS}'
  libraries: '-lm -latomic'
  extraCommands: ''
  alwaysShowCompilerOutput: true
cpp:
  compiler: 'g++'
  standard: 'c++17'
  optimization: 'O2'
  flags: '${COMPILER_FLAGS}'
  libraries: '-lm -latomic'
  extraCommands: ''
  alwaysShowCompilerOutput: true`

/** Top-level headmatter keys this script owns. */
const OWNED = new Set([
  ...SHARED.split('\n')
    .filter(line => /^\S+:/.test(line))
    .map(line => line.split(':')[0]),
  'title',
  'info',
])

const AUTHOR = 'Crudu Cristian'

const DECKS = [
  {
    dir: path.join(SLIDES_DIR, '00-hub'),
    title: 'Fundamentele Programării',
    info: `Fundamentele Programării · ${AUTHOR}`,
  },
  ...registry.lessons.map(lesson => ({
    dir: path.join(SLIDES_DIR, lesson.slug),
    title: `FP · ${lesson.title}`,
    info: `${lesson.title} — ${lesson.description} · ${AUTHOR}`,
  })),
]

/**
 * Drop the keys this script owns from a deck's own headmatter half.
 *
 * Line-based rather than YAML-parsed: headmatter is a flat mapping whose values
 * are either scalars or indented blocks, and round-tripping it through a YAML
 * library would reformat the parts we deliberately leave alone.
 */
function stripOwned(yaml) {
  const kept = []
  let dropping = false

  for (const line of yaml.split('\n')) {
    const topLevel = /^(\S+):/.exec(line)
    if (topLevel) dropping = OWNED.has(topLevel[1])
    // Continuation lines (indented, or `- item`) belong to the last key seen.
    else if (!/^(\s|-)/.test(line) && line.trim() !== '') dropping = false

    if (!dropping) kept.push(line)
  }

  return kept.join('\n').replace(/\n{3,}/g, '\n\n').trim()
}

function headmatterFor(deck, own) {
  return [
    `title: '${deck.title.replace(/'/g, "''")}'`,
    `info: '${deck.info.replace(/'/g, "''")}'`,
    own,
    MARKER,
    SHARED,
  ]
    .filter(part => part !== '')
    .join('\n')
}

function rewrite(deck) {
  const file = path.join(deck.dir, 'slides.md')
  if (!fs.existsSync(file)) return { name: path.basename(deck.dir), skipped: true }

  const source = fs.readFileSync(file, 'utf8')
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(source)
  if (!match) {
    throw new Error(`${file}: no headmatter block — a deck must start with '---'`)
  }

  // Everything the deck itself owns: above the marker on later runs, the whole
  // block minus the owned keys on the first one.
  const existing = match[1]
  const markerAt = existing.search(MARKER_RE)
  const own = stripOwned(markerAt === -1 ? existing : existing.slice(0, markerAt))

  const updated = source.replace(match[0], `---\n${headmatterFor(deck, own)}\n---\n`)
  const changed = updated !== source

  if (changed) fs.writeFileSync(file, updated, 'utf8')
  return { name: path.basename(deck.dir), changed }
}

function main() {
  const check = process.argv.includes('--check')
  const stale = []

  for (const deck of DECKS) {
    const before = fs.existsSync(path.join(deck.dir, 'slides.md'))
      ? fs.readFileSync(path.join(deck.dir, 'slides.md'), 'utf8')
      : null

    const result = rewrite(deck)

    if (result.skipped) {
      console.log(`  ⚠️  ${result.name}: no slides.md — skipped`)
      continue
    }

    if (result.changed) {
      stale.push(result.name)
      if (check) fs.writeFileSync(path.join(deck.dir, 'slides.md'), before, 'utf8')
      console.log(`  ${check ? '❌' : '✅'} ${result.name}`)
    } else {
      console.log(`  ·  ${result.name} (up to date)`)
    }
  }

  if (check && stale.length) {
    console.error(`\nHeadmatter is stale in: ${stale.join(', ')}`)
    console.error('Run: pnpm sync-headmatter')
    process.exit(1)
  }
}

main()
